    64→export const DICTIONARY_API = {
    65→    BASE: '/api/v1/dictionary',
    66→    list: (type: DictionaryType) => `/api/v1/dictionary/${type}`,
    67→    search: (type: DictionaryType) => `/api/v1/dictionary/${type}/search`,
    68→    create: () => '/api/v1/dictionary',
    69→    update: (id: string) => `/api/v1/dictionary/${id}`,
    70→    delete: (id: string) => `/api/v1/dictionary/${id}`,
    71→    compile: () => '/api/v1/dictionary/compile',
    72→    compileType: (type: DictionaryType) => `/api/v1/dictionary/compile/${type}`,
    73→} as const;
    74→
    75→/**
    76→ * Backend paginated response format
    77→ * Matches Spring Boot PagedResponse<Dictionary>
    78→ */
    79→export interface BackendPagedResponse {
    80→    items: BackendDictionary[];
    81→    total: number;
    82→    page: number;
    83→    size: number;
    84→    totalPages: number;
    85→}
    86→
    87→/**
    88→ * Backend cursor-based paginated response format
    89→ * Matches Spring Boot CursorPagedResponse<Dictionary>
    90→ */
    91→export interface BackendCursorResponse {
    92→    items: BackendDictionary[];
    93→    total: number;
    94→    cursor: string | null;  // Backend uses 'cursor', not 'nextCursor'
    95→    hasNext: boolean;
    96→}
