   601→                        </div>
   602→                    )}
   603→
   604→                    {/* SYNONYM Type Form */}
   605→                    {type === 'SYNONYM' && (
   606→                        <>
   607→                            <div className="space-y-3">
   608→                                <Label>매핑 방향</Label>
   609→                                <RadioGroup
